# Fonction C - 50 premiers nombres premiers

## Approche : Crible d'Ératosthène simplifié

```c
#include <stdio.h>
#include <stdbool.h>
#include <math.h>

/**
 * Vérifie si un nombre est premier
 */
bool est_premier(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;

    for (int i = 3; i <= (int)sqrt(n); i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

/**
 * Initialise un tableau avec les 50 premiers nombres premiers
 * @param tableau : tableau de taille au moins 50
 */
void initialiser_premiers(int tableau[], int taille) {
    int count = 0;
    int candidat = 2;

    while (count < taille) {
        if (est_premier(candidat)) {
            tableau[count] = candidat;
            count++;
        }
        candidat++;
    }
}

// ──────────────────────────────────────────
int main() {
    int premiers[50];

    initialiser_premiers(premiers, 50);

    printf("Les 50 premiers nombres premiers :\n");
    for (int i = 0; i < 50; i++) {
        printf("%4d", premiers[i]);
        if ((i + 1) % 10 == 0) printf("\n");
    }

    return 0;
}
```

