        if (sauce)     std::cout << "  Sauce     : " << sauce->getName()     << std::endl;
        if (cheese)    std::cout << "  Cheese    : " << cheese->getName()    << std::endl;
        if (!veggies.empty()) {
            std::cout << "  Veggies   : ";
            for (size_t i = 0; i < veggies.size(); ++i) {
                std::cout << veggies[i]->getName();
                if (i < veggies.size() - 1) std::cout << ", ";
