## Pizza Store - Factory Method Pattern

```cpp
// ============================================================
// ABSTRACT PIZZA STORE - defines the Factory Method
// ============================================================

class PizzaStore {
public:
    // Template method - uses factory method internally
    std::shared_ptr<Pizza> orderPizza(const std::string& type) {
        std::shared_ptr<Pizza> pizza = createPizza(type); // << FACTORY METHOD

        std::cout << "\n--- Making a " << pizza->getName() << " ---" << std::endl;
        pizza->prepare();
        pizza->bake();
        pizza->cut();
        pizza->box();

        return pizza;
    }

    // *** FACTORY METHOD - subclasses must implement this ***
    virtual std::shared_ptr<Pizza> createPizza(const std::string& type) = 0;

    virtual ~PizzaStore() = default;
};

