Here's a JavaScript function that creates an N-sided regular polygon SVG:

```javascript
function createRegularPolygon(N, options = {}) {
  const {
    size = 200,
    fill = "#4A90D9",
    stroke = "#2C5F8A",
    strokeWidth = 2,
    backgroundColor = "none",
  } = options;

  if (N < 3) {
    throw new Error("A polygon must have at least 3 sides");
  }

  const cx = size / 2;
  const cy = size / 2;
  const radius = (size / 2) * 0.85;

  // Calculate vertices
  const points = [];
  for (let i = 0; i < N; i++) {
    const angle = (2 * Math.PI * i) / N - Math.PI / 2; // Start from top
    const x = cx + radius * Math.cos(angle);
    const y = cy + radius * Math.sin(angle);
    points.push(`${x.toFixed(2)},${y.toFixed(2)}`);
  }

  const pointsStr = points.join(" ");

  const svg = `
    <svg 
      xmlns="http://www.w3.org/2000/svg" 
      width="${size}" 
      height="${size}" 
      viewBox="0 0 ${size} ${size}"
    >
      <rect width="${size}" height="${size}" fill="${backgroundColor}" />
      <polygon
        points="${pointsStr}"
        fill="${fill}"
        stroke="${stroke}"
        stroke-width="${strokeWidth}"
        stroke-linejoin="round"
      />
    </svg>
  `.trim();

  return svg;
}
```

---

## Usage Examples

```javascript
// Basic usage - create a pentagon
const pentagonSVG = createRegularPolygon(5);
console.log(pentagonSVG);

// Create a hexagon with custom options
const hexagonSVG = createRegularPolygon(6, {
  size: 300,
  fill: "#FF6B6B",
  stroke: "#C0392B",
  strokeWidth: 3,
});

// Inject into DOM
document.getElementById("container").innerHTML = hexagonSVG;

// Create multiple polygons
for (let n = 3; n <= 8; n++) {
  const svg = createRegularPolygon(n, {
    size: 150,
    fill: `hsl(${(n * 40) % 360}, 70%, 60%)`,
    stroke: `hsl(${(n * 40) % 360}, 70%, 40%)`,
  });

  const wrapper = document.createElement("div");
  wrapper.innerHTML = svg;
  document.body.appendChild(wrapper);
}
```

---

## Output Preview

| N | Shape |
|---|-------|
| 3 | Triangle |
| 4 | Square |
| 5 | Pentagon |
| 6 | Hexagon |
| 8 | Octagon |
| 12 | Dodecagon |

---

## How It Works

```
1. Center point (cx, cy) = size / 2
2. For each vertex i (0 to N-1):
   angle = (2π × i / N) - π/2   ← offset to start at top
   x = cx + radius × cos(angle)
   y = cy + radius × sin(angle)
3. Join all points into SVG <polygon>
```

The `-π/2` offset rotates the polygon so the **first vertex points upward** instead of to the right.

## Форма с условной валидацией через Formik + Yup

```jsx
import React from 'react';
import { useFormik } from 'formik';
import * as Yup from 'yup';

const validationSchema = Yup.object({
  checkbox: Yup.boolean(),
  inputValue: Yup.string().when('checkbox', {
    is: false,
    then: (schema) => schema.required('Поле обязательно для заполнения'),
    otherwise: (schema) => schema.notRequired(),
  }),
});

const MyForm = () => {
  const formik = useFormik({
    initialValues: {
      checkbox: false,
      inputValue: '',
    },
    validationSchema,
    onSubmit: (values) => {
      alert(JSON.stringify(values, null, 2));
    },
  });

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>Форма с условной валидацией</h2>

      <form onSubmit={formik.handleSubmit} style={styles.form}>

        {/* Чекбокс */}
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="checkbox"
            checked={formik.values.checkbox}
            onChange={formik.handleChange}
            style={styles.checkbox}
          />
          Я согласен (снимите галочку, чтобы поле стало обязательным)
        </label>

        {/* Инпут */}
        <div style={styles.inputWrapper}>
          <label style={styles.label}>
            Введите значение
            {!formik.values.checkbox && (
              <span style={styles.required}> *</span>
            )}
          </label>
          <input
            type="text"
            name="inputValue"
            value={formik.values.inputValue}
            onChange={formik.handleChange}
            onBlur={formik.handleBlur}
            placeholder="Введите текст..."
            style={{
              ...styles.input,
              borderColor:
                formik.touched.inputValue && formik.errors.inputValue
                  ? '#e74c3c'
                  : '#ccc',
            }}
          />
          {formik.touched.inputValue && formik.errors.inputValue && (
            <p style={styles.error}>{formik.errors.inputValue}</p>
          )}
        </div>

        {/* Кнопка */}
        <button type="submit" style={styles.button}>
          Отправить
        </button>

      </form>
    </div>
  );
};

