Here's the modified script with a 1 second cooldown between shots:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class BowAttack : MonoBehaviour
{
    public float arrowSpeed = 1;
    public GameObject arrowPrefab;

    Rigidbody2D rigid;

    // Track time since last shot
    private float lastFireTime = -1f;
    public float fireCooldown = 1f;

    void Start()
    {
        rigid = GetComponent<Rigidbody2D>();
    }

    void Update()
    {
        //Fire when we click the mouse
        if (Input.GetMouseButtonDown(0) && Time.time >= lastFireTime + fireCooldown)
        {
            // Update the last fire time
            lastFireTime = Time.time;

            //Get the vector from the player to the mouse
            Vector3 mousePos = Input.mousePosition;
            mousePos.z = 10;
            Vector3 worldPos = Camera.main.ScreenToWorldPoint(mousePos);
            Vector3 p2m = worldPos - transform.position;
            p2m.Normalize();

            //Spawn a bullet
            GameObject go = Instantiate<GameObject>(arrowPrefab);
            go.transform.position = transform.position;

            //Shoot it in that direction
            Rigidbody2D arrowRigid = go.GetComponent<Rigidbody2D>();
            arrowRigid.velocity = p2m * arrowSpeed;
        }
    }
}
```

The key changes made were:

* Added a **`lastFireTime`** variable to track when the last arrow was fired, initialized to `-1` so the player can shoot immediately
* Added a **`fireCooldown`** variable set to `1` second, which is public so you can adjust it in the Unity Inspector
* Added **`Time.time >= lastFireTime + fireCooldown`** to the if statement condition to check if enough time has passed
* Set **`lastFireTime = Time.time`** at the start of the if block to record when the arrow was fired

# Min Stack Implementation

## Overview
Design a stack that supports `push`, `pop`, and `getMin` operations all in **O(1)** time complexity.

## Approach
Use **two stacks**:
1. **Main stack** - stores all values
2. **Min stack** - tracks minimum values at each state

---

## Code

```java
class MinStack {

    // Main stack to store all values
    private Stack<Integer> mainStack;

    // Auxiliary stack to track minimum values
    private Stack<Integer> minStack;

    /** Initialize the MinStack */
    public MinStack() {
        mainStack = new Stack<>();
        minStack = new Stack<>();
    }

    /**
     * Push element onto stack
     * Time Complexity: O(1)
     */
    public void push(int val) {
        mainStack.push(val);

        // Push to minStack if:
        // 1. minStack is empty
        // 2. val is less than or equal to current minimum
        if (minStack.isEmpty() || val <= minStack.peek()) {
            minStack.push(val);
        }
    }

    /**
     * Remove top element from stack
     * Time Complexity: O(1)
     */
    public void pop() {
        if (mainStack.isEmpty()) {
            throw new EmptyStackException();
        }

        int removedVal = mainStack.pop();

        // If removed value equals current minimum, pop from minStack too
        if (removedVal == minStack.peek()) {
            minStack.pop();
        }
    }

    /**
     * Get top element of stack
     * Time Complexity: O(1)
     */
    public int top() {
        if (mainStack.isEmpty()) {
            throw new EmptyStackException();
        }
        return mainStack.peek();
    }

    /**
     * Retrieve minimum element in stack
     * Time Complexity: O(1)
     */
    public int getMin() {
        if (minStack.isEmpty()) {
            throw new EmptyStackException();
        }
        return minStack.peek();
    }

    /**
     * Check if stack is empty
     */
    public boolean isEmpty() {
        return mainStack.isEmpty();
    }

    /**
     * Get size of stack
     */
    public int size() {
        return mainStack.size();
    }
}
```

---

## Test / Driver Code

```java
public class Main {
    public static void main(String[] args) {
        MinStack minStack = new MinStack();

        // Test 1: Basic push and getMin
        System.out.println("=== Test 1: Basic Operations ===");
        minStack.push(5);
        minStack.push(3);
        minStack.push(7);
        minStack.push(3);
        minStack.push(2);

        System.out.println("Top: "    + minStack.top());    // Expected: 2
        System.out.println("Min: "    + minStack.getMin()); // Expected: 2

        // Test 2: Pop and check min updates
        System.out.println("\n=== Test 2: Pop Operations ===");
        minStack.pop(); // Remove 2
        System.out.println("After pop(2) -> Min: " + minStack.getMin()); // Expected: 3

        minStack.pop(); // Remove 3
        System.out.println("After pop(3) -> Min: " + minStack.getMin()); // Expected: 3

        minStack.pop(); // Remove 7
        System.out.println("After pop(7) -> Min: " + minStack.getMin()); // Expected: 3

        minStack.pop(); // Remove 3
        System.out.println("After pop(3) -> Min: " + minStack.getMin()); // Expected: 5

        // Test 3: Single element
        System.out.println("\n=== Test 3: Single Element ===");
        minStack.pop(); // Remove 5
        System.out.println("Stack empty: " + minStack.isEmpty()); // Expected: true

        // Test 4: Negative numbers
        System.out.println("\n=== Test 4: Negative Numbers ===");
        minStack.push(-1);
        minStack.push(-5);
        minStack.push(0);
        System.out.println("Min: " + minStack.getMin()); // Expected: -5
        minStack.pop();
        System.out.println("After pop(0) -> Min: " + minStack.getMin()); // Expected: -5
    }
}
```

