<script>
    // ===== Upload de imagens =====
    const imageInput = document.getElementById('imageInput');
    const imagePreview = document.getElementById('imagePreview');
    const dropZone = document.getElementById('dropZone');
    let selectedImages = [];

    imageInput.addEventListener('change', handleImageSelect);

    function handleImageSelect(e) {
        const files = Array.from(e.target.files);
        files.forEach(file => {
            if (file.size > 5 * 1024 * 1024) {
                alert(`A imagem "${file.name}" é maior que 5MB!`);
                return;
            }
            if (!file.type.startsWith('image/')) {
                alert(`"${file.name}" não é uma imagem válida!`);
                return;
            }
            addImagePreview(file);
        });
    }

    function addImagePreview(file) {
        const id = Date.now() + Math.random();
        selectedImages.push({ id, file });

        const reader = new FileReader();
        reader.onload = function(e) {
            const item = document.createElement('div');
            item.className = 'image-preview-item';
            item.id = `img-${id}`;
            item.innerHTML = `
                <img src="${e.target.result}" alt="${file.name}">
                <button class="remove-btn" onclick="removeImage(${id})" title="Remover">✕</button>
            `;
            imagePreview.appendChild(item);
        };
        reader.readAsDataURL(file);
    }

    function removeImage(id) {
        selectedImages = selectedImages.filter(img => img.id !== id);
        const el = document.getElementById(`img-${id}`);
        if (el) el.remove();
    }

    // Drag and Drop
    dropZone.addEventListener('dragover', (e) => {
        e.preventDefault();
        dropZone.classList.add('dragover');
    });

    dropZone.addEventListener('dragleave', () => {
        dropZone.classList.remove('dragover');
    });

    dropZone.addEventListener('drop', (e) => {
        e.preventDefault();
        dropZone.classList.remove('dragover');
        const files = Array.from(e.dataTransfer.files);
        files.forEach(file => {
            if (file.type.startsWith('image/')) {
                if (file.size <= 5 * 1024 * 1024) {
                    addImagePreview(file);
                } else {
                    alert(`A imagem "${file.name}" é maior que 5MB!`);
                }
            }
        });
    });

    // ===== Contador de caracteres =====
    const titleInput = document.getElementById('titleInput');
    const titleCounter = document.getElementById('titleCounter');
    const descriptionInput = document.getElementById('descriptionInput');
    const descCounter = document.getElementById('descCounter');

    titleInput.addEventListener('input', () => {
        const count = titleInput.value.length;
        titleCounter.textContent = `${count} / 100`;
        titleCounter.className = 'char-counter' + (count > 80 ? (count > 95 ? ' error' : ' warning') : '');
    });

    descriptionInput.addEventListener('input', () => {
        const count = descriptionInput.value.length;
        descCounter.textContent = `${count} / 500`;
        descCounter.className = 'char-counter' + (count > 400 ? (count > 480 ? ' error' : ' warning') : '');
    });

    // ===== Tags =====
    const tagInput = document.getElementById('tagInput');
    const tagsContainer = document.getElementById('tagsContainer');
    let tags = [];

    tagInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            addTag();
        }
    });

    function addTag() {
        const value = tagInput.value.trim().toLowerCase();
        if (!value) return;
        if (tags.includes(value)) {
            alert('Essa tag já foi adicionada!');
            return;
        }
        if (tags.length >= 10) {
            alert('Máximo de 10 tags permitido!');
            return;
        }

        tags.push(value);
        renderTags();
        tagInput.value = '';
        tagInput.focus();
    }

    function removeTag(value) {
        tags = tags.filter(t => t !== value);
        renderTags();
    }

    function renderTags() {
        tagsContainer.innerHTML = '';
        tags.forEach(tag => {
            const el = document.createElement('div');
            el.className = 'tag';
            el.innerHTML = `#${tag} <button onclick="removeTag('${tag}')" title="Remover tag">✕</button>`;
            tagsContainer.appendChild(el);
        });
    }

    // ===== Formulário de envio =====
    document.getElementById('uploadForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const title = titleInput.value.trim();
        if (!title) {
            alert('Por favor, preencha o título!');
            titleInput.focus();
            return;
        }

        const submitBtn = document.getElementById('submitBtn');
        const progressContainer = document.getElementById('progressContainer');
        const progressFill = document.getElementById('progressFill');
        const progressPercent = document.getElementById('progressPercent');
        const successMessage = document.getElementById('successMessage');

        submitBtn.disabled = true;
        submitBtn.textContent = '⏳ Enviando...';
        progressContainer.classList.add('active');
        successMessage.classList.remove('show');

        // Simulação de progresso
        let progress = 0;
        const interval = setInterval(() => {
            progress += Math.random() * 20;
            if (progress >= 100) {
                progress = 100;
                clearInterval(interval);

                progressFill.style.width = '100%';
                progressPercent.textContent = '100%';

                setTimeout(() => {
                    progressContainer.classList.remove('active');
                    successMessage.classList.add('show');
                    submitBtn.disabled = false;
                    submitBtn.textContent = '🚀 Enviar Conteúdo';

                    // Log dos dados (simulado)
                    console.log('📤 Dados enviados:', {
                        titulo: title,
                        descricao: descriptionInput.value,
                        categoria: document.getElementById('categorySelect').value,
                        tags: tags,
                        imagens: selectedImages.map(i => i.file.name)
                    });
                }, 500);
            }

            progressFill.style.width = `${Math.min(progress, 100)}%`;
            progressPercent.textContent = `${Math.round(Math.min(progress, 100))}%`;
        }, 200);
    });
</script>

</body>
</html>
