### Step 4: API Handler Class

```php
<?php
// includes/class-vicuna-api.php

if (!defined('ABSPATH')) exit;

class VicunaAPI {

    private $api_url;
    private $api_key;
    private $model;
    private $max_tokens;
    private $temperature;

    public function __construct() {
        $this->api_url    = get_option('vicuna_api_url', 'http://localhost:8000/v1');
        $this->api_key    = get_option('vicuna_api_key', 'EMPTY'); // FastChat default
        $this->model      = get_option('vicuna_model', 'vicuna-7b-v1.5');
        $this->max_tokens = get_option('vicuna_max_tokens', 512);
        $this->temperature = get_option('vicuna_temperature', 0.7);
    }

    /**
     * Send a message to Vicuna API
     */
    public function send_message(string $message, array $history = []): string|WP_Error {

        $messages = $this->build_messages($message, $history);

        $body = json_encode([
            'model'       => $this->model,
            'messages'    => $messages,
            'max_tokens'  => (int) $this->max_tokens,
            'temperature' => (float) $this->temperature,
        ]);

        $response = wp_remote_post(
            $this->api_url . '/chat/completions',
            [
                'timeout' => 60,
                'headers' => [
                    'Content-Type'  => 'application/json',
                    'Authorization' => 'Bearer ' . $this->api_key,
                ],
                'body' => $body,
            ]
        );

        // Handle request errors
        if (is_wp_error($response)) {
            return new WP_Error('api_error', $response->get_error_message());
        }

        $status_code = wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($status_code !== 200) {
            return new WP_Error(
                'api_error',
                $body['error']['message'] ?? 'Unknown API error'
            );
        }

        return $body['choices'][0]['message']['content'] ?? '';
    }

    /**
     * Build messages array with system prompt
     */
    private function build_messages(string $message, array $history): array {
        $system_prompt = get_option(
            'vicuna_system_prompt',
            'You are a helpful assistant.'
        );

        $messages = [
            ['role' => 'system', 'content' => $system_prompt]
        ];

        // Add conversation history
        foreach ($history as $entry) {
            $messages[] = [
                'role'    => sanitize_text_field($entry['role']),
                'content' => sanitize_text_field($entry['content']),
            ];
        }

        // Add current message
        $messages[] = ['role' => 'user', 'content' => $message];

        return $messages;
    }
}
```

