### Step 7: Frontend JavaScript

```javascript
// assets/chat.js
jQuery(document).ready(function ($) {
    const messagesContainer = $("#vicuna-messages");
    const input = $("#vicuna-input");
    const sendBtn = $("#vicuna-send");
    let isLoading = false;

    // Send on button click
    sendBtn.on("click", sendMessage);

    // Send on Enter (Shift+Enter for new line)
    input.on("keydown", function (e) {
        if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    });

    function sendMessage() {
        const message = input.val().trim();
        if (!message || isLoading) return;

        appendMessage("user", message);
        input.val("");
        setLoading(true);

        $.ajax({
            url: vicunaConfig.ajaxUrl,
            type: "POST",
            data: {
                action: "vicuna_send_message",
                nonce: vicunaConfig.nonce,
                message: message,
            },
            success: function (response) {
                if (response.success) {
                    appendMessage("assistant", response.data.response);
                } else {
                    appendMessage("error", "Error: " + response.data.message);
                }
            },
            error: function () {
                appendMessage("error", "Connection error. Please try again.");
            },
            complete: function () {
                setLoading(false);
            },
        });
    }

    function appendMessage(role, content) {
        const messageDiv = $("<div>")
            .addClass("vicuna-message " + role)
            .html("<span>" + escapeHtml(content) + "</span>");

        messagesContainer.append(messageDiv);
        messagesContainer.scrollTop(messagesContainer[0].scrollHeight);
    }

    function setLoading(loading) {
        isLoading = loading;
        sendBtn.prop("disabled", loading);
        sendBtn.text(loading ? "Sending..." : "Send");

        if (loading) {
            appendMessage("assistant loading", "Thinking...");
        } else {
            $(".vicuna-message.loading").remove();
        }
    }

    function escapeHtml(text) {
        return $("<div>").text(text).html();
    }
});
