                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
                Google
            </button>
            <button class="btn-social" type="button" onclick="socialLogin('GitHub')">
                <svg viewBox="0 0 24 24" fill="#24292e">
                    <path d="M12 1.27a11 11 0 00-3.48 21.46c.55.09.73-.28.73-.55v-1.84c-3.03.64-3.67-1.46-3.67-1.46-.55-1.29-1.28-1.65-1.28-1.65-.92-.65.1-.65.1-.65 1.1 0 1.73 1.1 1.73 1.1.92 1.65 2.57 1.2 3.21.92a2 2 0 01.64-1.47c-2.47-.27-5.04-1.19-5.04-5.5 0-1.1.46-2.1 1.2-2.84a3.76 3.76 0 010-2.93s.91-.28 3.11 1.1c1.8-.49 3.7-.49 5.5 0 2.1-1.38 3.02-1.1 3.02-1.1a3.76 3.76 0 010 2.93c.83.74 1.2 1.74 1.2 2.84 0 4.31-2.57 5.23-5.04 5.5.45.37.82.92.82 2.02v3.03c0 .27.1.64.73.55A11 11 0 0012 1.27"/>
                </svg>
                GitHub
            </button>
        </div>

        <!-- Rodapé -->
        <div class="form-footer">
            Não tem conta? <a href="#" id="registerLink">Cadastre-se</a>
        </div>

    </div>

    <script>
        // =============================
        // Credenciais de Demonstração
        // =============================
        const VALID_USERS = [
            { email: "admin@email.com", password: "123456" },
            { email: "user@email.com",  password: "senha123" }
        ];

        // =============================
        // Elementos do DOM
        // =============================
        const loginForm      = document.getElementById('loginForm');
        const emailInput     = document.getElementById('email');
        const passwordInput  = document.getElementById('password');
        const btnLogin       = document.getElementById('btnLogin');
        const btnText        = document.getElementById('btnText');
        const spinner        = document.getElementById('spinner');
        const errorMessage   = document.getElementById('errorMessage');
        const errorText      = document.getElementById('errorText');
        const successMessage = document.getElementById('successMessage');
        const togglePassword = document.getElementById('togglePassword');
        const emailGroup     = document.getElementById('emailGroup');
        const passwordGroup  = document.getElementById('passwordGroup');
        const forgotLink     = document.getElementById('forgotLink');
        const registerLink   = document.getElementById('registerLink');

        // =============================
        // Mostrar / Ocultar Senha
        // =============================
        togglePassword.addEventListener('click', () => {
            const isPassword = passwordInput.type === 'password';
            passwordInput.type = isPassword ? 'text' : 'password';

            togglePassword.innerHTML = isPassword
                ? `<svg id="eyeClosed" viewBox="0 0 24 24" style="width:18px;height:18px;fill:#a0aec0">
                        <path d="M12 7c2.76 0 5 2.24 5 5 0 .65-.13 1.26-.36 1.83l2.92 2.92c1.51-1.26 2.7-2.89 3.43-4.75-1.73-4.39-6-7.5-11-7.5-1.4 0-2.74.25-3.98.7l2.16 2.16C10.74 7.13 11.35 7 12 7zM2 4.27l2.28 2.28.46.46C3.08 8.3 1.78 10.02 1 12c1.73 4.39 6 7.5 11 7.5 1.55 0 3.03-.3 4.38-.84l.42.42L19.73 22 21 20.73 3.27 3 2 4.27zM7.53 9.8l1.55 1.55c-.05.21-.08.43-.08.65 0 1.66 1.34 3 3 3 .22 0 .44-.03.65-.08l1.55 1.55c-.67.33-1.41.53-2.2.53-2.76 0-5-2.24-5-5 0-.79.2-1.53.53-2.2zm4.31-.78l3.15 3.15.02-.16c0-1.66-1.34-3-3-3l-.17.01z"/>
                   </svg>`
                : `<svg id="eyeOpen" viewBox="0 0 24 24" style="width:18px;height:18px;fill:#a0aec0">
                        <path d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z"/>
                   </svg>`;
        });

        // =============================
        // Validação de campos
        // =============================
        function validateEmail(email) {
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
        }

        function setInputError(group) {
            group.classList.add('input-error');
        }

        function clearInputError(group) {
            group.classList.remove('input-error');
        }

        emailInput.addEventListener('input', () => {
            clearInputError(emailGroup);
            hideMessages();
        });

        passwordInput.addEventListener('input', () => {
            clearInputError(passwordGroup);
            hideMessages();
        });

        // =============================
        // Exibir / Ocultar Mensagens
        // =============================
        function showError(msg) {
            errorText.textContent = msg;
            errorMessage.classList.add('show');
            successMessage.classList.remove('show');
        }

        function showSuccess() {
            successMessage.classList.add('show');
            errorMessage.classList.remove('show');
        }

        function hideMessages() {
            errorMessage.classList.remove('show');
            successMessage.classList.remove('show');
        }

        // =============================
        // Simular Loading
        // =============================
        function setLoading(isLoading) {
            if (isLoading) {
                btnText.style.display = 'none';
                spinner.style.display = 'block';
                btnLogin.classList.add('loading');
            } else {
                btnText.style.display = 'block';
                spinner.style.display = 'none';
                btnLogin.classList.remove('loading');
            }
        }

        // =============================
        // Submit do Formulário
        // =============================
        loginForm.addEventListener('submit', function(e) {
            e.preventDefault();

            const email    = emailInput.value.trim();
            const password = passwordInput.value;
            let hasError   = false;

            hideMessages();

            // Validar e-mail
            if (!email) {
                setInputError(emailGroup);
                showError('Por favor, informe seu e-mail.');
                hasError = true;
            } else if (!validateEmail(email)) {
                setInputError(emailGroup);
                showError('Informe um e-mail válido.');
                hasError = true;
            }

            // Validar senha
            if (!password) {
                setInputError(passwordGroup);
                if (!hasError) showError('Por favor, informe sua senha.');
                hasError = true;
            } else if (password.length < 6) {
                setInputError(passwordGroup);
                if (!hasError) showError('A senha deve ter pelo menos 6 caracteres.');
                hasError = true;
            }

            if (hasError) return;

            // Simula requisição
            setLoading(true);

            setTimeout(() => {
                setLoading(false);

                const userFound = VALID_USERS.find(
                    u => u.email === email && u.password === password
                );

                if (userFound) {
                    showSuccess();
                    clearInputError(emailGroup);
                    clearInputError(passwordGroup);

                    // Redirecionar após 2 segundos
                    setTimeout(() => {
                        alert(`✅ Bem-vindo, ${email}!\n\nEm um projeto real, você seria redirecionado ao painel.`);
                    }, 1500);
                } else {
                    setInputError(emailGroup);
                    setInputError(passwordGroup);
                    showError('E-mail ou senha incorretos. Tente novamente.');
                }
            }, 1800);
        });

        // =============================
        // Login Social (Demo)
        // =============================
        function socialLogin(provider) {
            alert(`🔗 Login com ${provider}\n\nEm um projeto real, você seria redirecionado para o OAuth do ${provider}.`);
        }

        // =============================
        // Esqueci a Senha (Demo)
        // =============================
        forgotLink.addEventListener('click', (e) => {
            e.preventDefault();
            const email = emailInput.value.trim();
            if (email && validateEmail(email)) {
                alert(`📧 Link de recuperação enviado para:\n${email}`);
            } else {
                emailInput.focus();
                setInputError(emailGroup);
                showError('Informe seu e-mail para recuperar a senha.');
            }
        });

        // =============================
        // Cadastre-se (Demo)
        // =============================
        registerLink.addEventListener('click', (e) => {
            e.preventDefault();
            alert('📝 Em um projeto real, aqui abriria a página de Cadastro.');
        });
    </script>

</body>
</html>
```

