<!-- ══════════════ JAVASCRIPT ══════════════ -->
<script>
(function () {
  'use strict';

  /* ── Track Data ────────────────────────────────────────────────── */
  const TRACKS = [
    { title: 'Midnight Waves',  artist: 'Luna Ray',       emoji: '🌙', bg: 'linear-gradient(135deg,#1a1a40,#4a2080)', duration: '3:45', durationSec: 225 },
    { title: 'Blaze & Glory',   artist: 'The Infernos',   emoji: '🔥', bg: 'linear-gradient(135deg,#402010,#c04020)', duration: '4:02', durationSec: 242 },
    { title: 'Earthen Soul',    artist: 'Verdant Echo',   emoji: '🌿', bg: 'linear-gradient(135deg,#104030,#20c060)', duration: '3:28', durationSec: 208 },
    { title: 'Voltage',         artist: 'Static Drive',   emoji: '⚡', bg: 'linear-gradient(135deg,#201040,#8020c0)', duration: '3:55', durationSec: 235 },
    { title: 'Deep Current',    artist: 'Ocean Pulse',    emoji: '🌊', bg: 'linear-gradient(135deg,#101840,#2040b0)', duration: '4:15', durationSec: 255 },
    { title: 'Neon Phantom',    artist: 'Ghost Circuit',  emoji: '👻', bg: 'linear-gradient(135deg,#201030,#902090)', duration: '3:33', durationSec: 213 },
    { title: 'Solar Flare',     artist: 'Helio Drive',    emoji: '☀️', bg: 'linear-gradient(135deg,#402000,#d08000)', duration: '4:08', durationSec: 248 },
    { title: 'Crystal Rain',    artist: 'Prism Falls',    emoji: '💎', bg: 'linear-gradient(135deg,#104040,#20a0a0)', duration: '3:50', durationSec: 230 },
  ];

  /* ── State ─────────────────────────────────────────────────────── */
  let currentTrack = 0;
  let isPlaying    = false;
  let isShuffle    = false;
  let isRepeat     = false;
  let progressSec  = 0;
  let progressTimer = null;
  const likedTracks = new Set();

  /* ── DOM ───────────────────────────────────────────────────────── */
  const playerModal    = document.getElementById('playerModal');
  const miniPlayer     = document.getElementById('miniPlayer');
  const miniArt        = document.getElementById('miniArt');
  const miniTitle      = document.getElementById('miniTitle');
  const miniArtist     = document.getElementById('miniArtist');
  const miniPlayBtn    = document.getElementById('miniPlayBtn');
  const miniPlayIcon   = document.getElementById('miniPlayIcon');
  const miniProgressBar= document.getElementById('miniProgressBar');
  const miniPrev       = document.getElementById('miniPrev');
  const miniNext       = document.getElementById('miniNext');

  const playerArt      = document.getElementById('playerArt');
  const playerTitle    = document.getElementById('playerTitle');
  const playerArtist   = document.getElementById('playerArtist');
  const playerLike     = document.getElementById('playerLike');
  const mainPlayBtn    = document.getElementById('mainPlayBtn');
  const mainPlayIcon   = document.getElementById('mainPlayIcon');
  const progressBarWrap= document.getElementById('progressBarWrap');
  const progressBarFill= document.getElementById('progressBarFill');
  const currentTimeEl  = document.getElementById('currentTime');
  const totalTimeEl    = document.getElementById('totalTime');
  const shuffleBtn     = document.getElementById('shuffleBtn');
  const repeatBtn      = document.getElementById('repeatBtn');
  const prevBtn        = document.getElementById('prevBtn');
  const nextBtn        = document.getElementById('nextBtn');
  const closePlayer    = document.getElementById('closePlayer');
  const trackList      = document.getElementById('trackList');
  const navItems       = document.querySelectorAll('.nav-item');
  const chips          = document.querySelectorAll('.chip');

  /* ── SVG Icons ─────────────────────────────────────────────────── */
  const ICON_PLAY  = `<polygon points="5,3 19,12 5,21"/>`;
  const ICON_PAUSE = `<rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/>`;

  function playIcon(el)  { el.innerHTML = ICON_PLAY;  }
  function pauseIcon(el) { el.innerHTML = ICON_PAUSE; }

  /* ── Build Track List ──────────────────────────────────────────── */
  function buildTrackList() {
    trackList.innerHTML = '';
    TRACKS.forEach((t, i) => {
      const item = document.createElement('div');
      item.className = 'track-item' + (i === currentTrack ? ' active' : '');
      item.setAttribute('role', 'listitem');
      item.dataset.index = i;
      item.innerHTML = `
        <div class="track-item__num">${i + 1}</div>
        <div class="track-item__art" style="background:${t.bg}">${t.emoji}</div>
        <div class="track-item__info">
          <div class="track-item__name">${t.title}</div>
          <div class="track-item__artist">${t.artist}</div>
        </div>
        <div class="track-item__right">
          <span class="track-item__dur">${t.duration}</span>
          <button class="like-btn${likedTracks.has(i) ? ' liked' : ''}" aria-label="Like ${t.title}" data-like-index="${i}">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="${likedTracks.has(i) ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
            </svg>
          </button>
        </div>
      `;
      trackList.appendChild(item);
    });
  }

  /* ── Update All UI for Current Track ──────────────────────────── */
  function updateTrackUI() {
    const t = TRACKS[currentTrack];

    // Mini player
    miniArt.textContent   = t.emoji;
    miniArt.style.background = t.bg;
    miniTitle.textContent = t.title;
    miniArtist.textContent = t.artist;

    // Full player
    playerArt.textContent = t.emoji;
    playerArt.style.background = t.bg;
    playerTitle.textContent = t.title;
    playerArtist.textContent = t.artist;
    totalTimeEl.textContent = t.duration;

    // Like state
    const liked = likedTracks.has(currentTrack);
    playerLike.querySelector('svg').setAttribute('fill', liked ? '#f87171' : 'none');
    playerLike.querySelector('svg').setAttribute('stroke', liked ? '#f87171' : 'currentColor');

    // Highlight active track in list
    document.querySelectorAll('.track-item').forEach((el, i) => {
      el.classList.toggle('active', i === currentTrack);
    });

    // Reset progress
    progressSec = 0;
    updateProgress();
  }

  /* ── Progress ──────────────────────────────────────────────────── */
  function fmtTime(s) {
    const m = Math.floor(s / 60);
    const ss = String(Math.floor(s % 60)).padStart(2, '0');
    return `${m}:${ss}`;
  }

  function updateProgress() {
    const total = TRACKS[currentTrack].durationSec;
    const pct   = (progressSec / total) * 100;
    progressBarFill.style.width  = pct + '%';
    miniProgressBar.style.width  = pct + '%';
    currentTimeEl.textContent    = fmtTime(progressSec);
    progressBarWrap.setAttribute('aria-valuenow', Math.round(pct));
  }

  function startTimer() {
    clearInterval(progressTimer);
    progressTimer = setInterval(() => {
      const total = TRACKS[currentTrack].durationSec;
      if (progressSec < total) {
        progressSec++;
        updateProgress();
      } else {
        // Track ended
        if (isRepeat) {
          progressSec = 0;
        } else {
          goNext();
        }
      }
    }, 1000);
  }

  function stopTimer() { clearInterval(progressTimer); }

  /* ── Play / Pause ──────────────────────────────────────────────── */
  function setPlaying(val) {
    isPlaying = val;
    if (isPlaying) {
      pauseIcon(mainPlayIcon);
      pauseIcon(miniPlayIcon);
      playerArt.classList.add('playing');
      startTimer();
    } else {
      playIcon(mainPlayIcon);
      playIcon(miniPlayIcon);
      playerArt.classList.remove('playing');
      stopTimer();
    }
  }

  function togglePlay() { setPlaying(!isPlaying); }

  /* ── Navigation ────────────────────────────────────────────────── */
  function loadTrack(index) {
    currentTrack = (index + TRACKS.length) % TRACKS.length;
    progressSec  = 0;
    updateTrackUI();
    if (isPlaying) startTimer();
  }

  function goPrev() {
    if (progressSec > 3) { progressSec = 0; updateProgress(); return; }
    loadTrack(isShuffle ? Math.floor(Math.random() * TRACKS.length) : currentTrack - 1);
  }

  function goNext() {
    loadTrack(isShuffle ? Math.floor(Math.random() * TRACKS.length) : currentTrack + 1);
  }

  /* ── Modal Open / Close ────────────────────────────────────────── */
  function openPlayer() {
    playerModal.classList.add('open');
    playerModal.focus();
    document.body.style.overflow = 'hidden';
  }

  function closePlayerFn() {
    playerModal.classList.remove('open');
    document.body.style.overflow = '';
  }

  /* ── Like Toggle ───────────────────────────────────────────────── */
  function toggleLike(index) {
    if (likedTracks.has(index)) likedTracks.delete(index);
    else likedTracks.add(index);
    buildTrackList();
    if (index === currentTrack) {
      const liked = likedTracks.has(currentTrack);
      playerLike.querySelector('svg').setAttribute('fill', liked ? '#f87171' : 'none');
      playerLike.querySelector('svg').setAttribute('stroke', liked ? '#f87171' : 'currentColor');
    }
  }

  /* ── Seek on Progress Bar Click ────────────────────────────────── */
  function seekTo(e) {
    const rect = progressBarWrap.getBoundingClientRect();
    const pct  = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    progressSec = Math.floor(pct * TRACKS[currentTrack].durationSec);
    updateProgress();
  }

  /* ── Volume Slider Gradient ────────────────────────────────────── */
  const volumeSlider = document.getElementById('volumeSlider');
  function updateVolumeStyling() {
    const v = volumeSlider.value;
    volumeSlider.style.background = `linear-gradient(to right, var(--accent) ${v}%, var(--bg-surface) ${v}%)`;
  }

  /* ── Chip Active ───────────────────────────────────────────────── */
  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      chips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
    });
  });

  /* ── Bottom Nav ────────────────────────────────────────────────── */
  navItems.forEach(item => {
    item.addEventListener('click', () => {
      navItems.forEach(n => { n.classList.remove('active'); n.removeAttribute('aria-current'); });
      item.classList.add('active');
      item.setAttribute('aria-current', 'page');
    });
  });

  /* ── Album Card Click ──────────────────────────────────────────── */
  document.querySelectorAll('.album-card').forEach(card => {
    card.addEventListener('click', () => {
      const idx = parseInt(card.dataset.trackIndex, 10);
      loadTrack(idx);
      setPlaying(true);
    });
  });

  /* ── Event Listeners ───────────────────────────────────────────── */
  miniPlayer.addEventListener('click', e => {
    if (!e.target.closest('.mini-player__controls')) openPlayer();
  });
  miniPlayer.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') openPlayer(); });

  closePlayer.addEventListener('click', closePlayerFn);

  mainPlayBtn.addEventListener('click', togglePlay);
  miniPlayBtn.addEventListener('click', e => { e.stopPropagation(); togglePlay(); });

  prevBtn.addEventListener('click', goPrev);
  nextBtn.addEventListener('click', goNext);
  miniPrev.addEventListener('click', e => { e.stopPropagation(); goPrev(); });
  miniNext.addEventListener('click', e => { e.stopPropagation(); goNext(); });

  shuffleBtn.addEventListener('click', () => {
    isShuffle = !isShuffle;
    shuffleBtn.classList.toggle('active', isShuffle);
    shuffleBtn.setAttribute('aria-pressed', isShuffle);
  });

  repeatBtn.addEventListener('click', () => {
    isRepeat = !isRepeat;
    repeatBtn.classList.toggle('active', isRepeat);
    repeatBtn.setAttribute('aria-pressed', isRepeat);
  });

  playerLike.addEventListener('click', () => toggleLike(currentTrack));

  progressBarWrap.addEventListener('click', seekTo);
  progressBarWrap.addEventListener('keydown', e => {
    const step = 5;
    if (e.key === 'ArrowRight') { progressSec = Math.min(progressSec + step, TRACKS[currentTrack].durationSec); updateProgress(); }
    if (e.key === 'ArrowLeft')  { progressSec = Math.max(progressSec - step, 0); updateProgress(); }
  });

  volumeSlider.addEventListener('input', updateVolumeStyling);

  // Track list click delegation
  trackList.addEventListener('click', e => {
    const likeBtn = e.target.closest('.like-btn');
    if (likeBtn) { toggleLike(parseInt(likeBtn.dataset.likeIndex, 10)); return; }
    const item = e.target.closest('.track-item');
    if (item) { loadTrack(parseInt(item.dataset.index, 10)); setPlaying(true); }
  });

  // Featured play button
  document.getElementById('featuredPlayBtn').addEventListener('click', e => {
    e.stopPropagation();
    loadTrack(0);
    setPlaying(true);
    openPlayer();
  });

  // Close modal on backdrop (outside the modal content) — handled by escape key
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && playerModal.classList.contains('open')) closePlayerFn();
  });

  /* ── Init ──────────────────────────────────────────────────────── */
  buildTrackList();
  updateTrackUI();
  updateVolumeStyling();

})();
</script>
</body>
</html>
