## Option 4: Using HttpClient with Ollama REST API

```csharp
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;

class VicunaClient
{
    private readonly HttpClient _httpClient;
    private const string BaseUrl = "http://localhost:11434";

    public VicunaClient()
    {
        _httpClient = new HttpClient
        {
            Timeout = TimeSpan.FromMinutes(5)
        };
    }

    public async Task<string> GenerateAsync(string prompt)
    {
        var request = new
        {
            model = "vicuna",
            prompt = prompt,
            stream = false
        };

        var json = JsonSerializer.Serialize(request);
        var content = new StringContent(json, Encoding.UTF8, "application/json");

        var response = await _httpClient.PostAsync($"{BaseUrl}/api/generate", content);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadFromJsonAsync<GenerateResponse>();
        return result?.Response ?? string.Empty;
    }

    public async IAsyncEnumerable<string> StreamGenerateAsync(string prompt)
    {
        var request = new
        {
            model = "vicuna",
            prompt = prompt,
            stream = true
        };

        var json = JsonSerializer.Serialize(request);
        var content = new StringContent(json, Encoding.UTF8, "application/json");

        var response = await _httpClient.PostAsync(
            $"{BaseUrl}/api/generate",
            content,
            HttpCompletionOption.ResponseHeadersRead);

        using var stream = await response.Content.ReadAsStreamAsync();
        using var reader = new StreamReader(stream);

        while (!reader.EndOfStream)
        {
            var line = await reader.ReadLineAsync();
            if (string.IsNullOrEmpty(line)) continue;

            var chunk = JsonSerializer.Deserialize<GenerateResponse>(line);
            if (chunk?.Response != null)
            {
                yield return chunk.Response;
            }
        }
    }

    public async Task<string> ChatAsync(List<ChatMessage> messages)
    {
        var request = new
        {
            model = "vicuna",
            messages = messages,
            stream = false
        };

        var json = JsonSerializer.Serialize(request);
        var content = new StringContent(json, Encoding.UTF8, "application/json");

        var response = await _httpClient.PostAsync($"{BaseUrl}/api/chat", content);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadFromJsonAsync<ChatResponse>();
        return result?.Message?.Content ?? string.Empty;
    }
}

public class GenerateResponse
{
    public string? Response { get; set; }
    public bool Done { get; set; }
}

public class ChatMessage
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
}

public class ChatResponse
{
    public ChatMessage? Message { get; set; }
    public bool Done { get; set; }
}

// Usage
class Program
{
    static async Task Main(string[] args)
    {
        var client = new VicunaClient();

        // Simple generation
        var response = await client.GenerateAsync("What is the capital of France?");
        Console.WriteLine(response);

        // Streaming
        Console.Write("Streaming: ");
        await foreach (var token in client.StreamGenerateAsync("Tell me a short story"))
        {
            Console.Write(token);
        }
        Console.WriteLine();

        // Chat
        var messages = new List<ChatMessage>
        {
            new() { Role = "system", Content = "You are a helpful assistant." },
            new() { Role = "user", Content = "Hello! How are you?" }
        };

        var chatResponse = await client.ChatAsync(messages);
        Console.WriteLine($"Chat: {chatResponse}");
    }
}
```

